main.script:

document.addEventListener("DOMContentLoaded", function () {
    // Scenario Presets Dictionary
    var presets = {
        mfg: {
            prompt: "Phân tích dữ liệu vi rung động tần số cao trên Trục chính CNC #4, đối chiếu cảnh báo cảm biến nhiệt, truy vết lịch sử bảo trì ERP và tự động sinh lệnh sửa chữa SAP.",
            output: "TRẠNG THÁI: HOÀN TẤT (Thời gian: 218ms)\n" +
                    "► [Bước 1] Thu nạp 12.000 mẫu gia tốc từ Trục chính CNC #4.\n" +
                    "► [Bước 2] Phát hiện đỉnh sóng hài 1,84kHz. Xác suất mỏi vòng bi: 98,4%.\n" +
                    "► [Bước 3] Đối soát BOM ERP: Cần phụ tùng vòng bi SKF Explorer 6208.\n" +
                    "► [Bước 4] Kiểm tra hàng rào bảo vệ tất định: ĐẠT. Đã tạo Lệnh sửa chữa #WO-89104 trong SAP MES.\n" +
                    "► [Bước 5] Tự động gửi cảnh báo khẩn đến Trưởng ca bảo trì qua Telegram/SMS."
        },
        telecom: {
            prompt: "Kiểm duyệt luồng video lô #18204 của MobiFone theo quy chuẩn truyền thông, phát hiện watermark trái phép, nội dung độc hại và vi phạm bản quyền.",
            output: "TRẠNG THÁI: HOÀN TẤT (Thời gian: 194ms)\n" +
                    "► [Bước 1] Thu nạp 420 khung hình chính H.264 ở tốc độ 60fps.\n" +
                    "► [Bước 2] Phân loại khung hình đa lớp: 0 khung hình độc hại, 0 vi phạm bản quyền.\n" +
                    "► [Bước 3] Bóc băng âm thanh: 100% tuân thủ quy chuẩn Phát thanh - Truyền hình Việt Nam.\n" +
                    "► [Bước 4] Đóng dấu sổ cái Watermark số với mã băm SHA-256 #7c9f...a81.\n" +
                    "► [Bước 5] Lô video được phê duyệt phát sóng tốc độ cao trên mạng CDN."
        },
        energy: {
            prompt: "Giám sát camera an ninh cổng Trạm biến áp 220kV, xác thực danh tính nhà thầu, kiểm tra mũ bảo hộ, dây an toàn và găng cách điện trước khi mở cổng xoay.",
            output: "TRẠNG THÁI: ĐÃ CẤP QUYỀN TRUY CẬP (Thời gian: 165ms)\n" +
                    "► [Bước 1] Nhận diện FaceID nhân sự nhà thầu: Nguyễn Văn H. (Mã #EVN-89412).\n" +
                    "► [Bước 2] Chứng chỉ An toàn Điện Bậc 4 còn hiệu lực đến 31/12/2027.\n" +
                    "► [Bước 3] Kiểm tra trang bị BHLĐ: Mũ cách điện Class-E (ĐẠT), Áo phản quang (ĐẠT), Găng cách điện (ĐẠT).\n" +
                    "► [Bước 4] Mở khóa cổng xoay an toàn #02 trong 15 giây.\n" +
                    "► [Bước 5] Ghi nhận nhật ký kiểm toán SCADA bất biến về trung tâm chỉ huy điều hành."
        },
        supply: {
            prompt: "Đánh giá mức tồn kho an toàn tế bào pin Lithium-Ion, mô phỏng biến động thời gian vận chuyển chuỗi cung ứng và chuẩn bị đơn đặt hàng bổ sung tự động.",
            output: "TRẠNG THÁI: ĐÃ TẠO ĐƠN ĐẶT HÀNG TỰ ĐỘNG (Thời gian: 232ms)\n" +
                    "► [Bước 1] Tồn kho hiện tại: 4.200 đơn vị (Mức tiêu hao: 680 đơn vị/ngày).\n" +
                    "► [Bước 2] Dự báo chậm trễ do nghẽn cảng biển: biến động +4,2 ngày.\n" +
                    "► [Bước 3] Chạm ngưỡng đặt hàng lại: Khởi tạo đơn mua 15.000 đơn vị từ nhà cung cấp cấp 1.\n" +
                    "► [Bước 4] Áp dụng phòng hộ biến động giá: Tiết kiệm 4,8% so với giá giao ngay.\n" +
                    "► [Bước 5] Chuyển tiếp hàng đợi phê duyệt 1-chạm của Giám đốc Tài chính (CFO)."
        }
    };

    // Console Preset Switcher
    var presetButtons = document.querySelectorAll(".mojo-prompt-btn");
    var promptInput = document.getElementById("mojo-console-prompt");
    var consoleOutput = document.getElementById("mojo-console-output");
    var runButton = document.getElementById("mojo-btn-run");
    var pipelineStatus = document.getElementById("mojo-pipeline-status");

    presetButtons.forEach(function (btn) {
        btn.addEventListener("click", function () {
            presetButtons.forEach(function (b) { b.classList.remove("active"); });
            btn.classList.add("active");
            var key = btn.getAttribute("data-preset");
            if (presets[key] && promptInput) {
                promptInput.value = presets[key].prompt;
            }
        });
    });

    // Run Agent Execution Animation
    if (runButton && promptInput && consoleOutput) {
        runButton.addEventListener("click", function () {
            runButton.disabled = true;
            if (pipelineStatus) pipelineStatus.textContent = "Đang thực thi Swarm Đa Tác Tử...";
            consoleOutput.textContent = "► [Giai đoạn 1] Phân tích mục đích & ranh giới chính sách...\n► [Giai đoạn 2] Truy xuất kho véc-tơ dữ liệu chủ quyền...";

            var stepEls = [
                document.getElementById("mojo-step-1"),
                document.getElementById("mojo-step-2"),
                document.getElementById("mojo-step-3"),
                document.getElementById("mojo-step-4"),
                document.getElementById("mojo-step-5")
            ];

            stepEls.forEach(function (el) {
                if (el) {
                    el.className = "badge bg-info text-dark p-2";
                }
            });

            setTimeout(function () {
                var activeBtn = document.querySelector(".mojo-prompt-btn.active");
                var key = activeBtn ? activeBtn.getAttribute("data-preset") : "mfg";
                var res = presets[key] ? presets[key].output : presets.mfg.output;
                consoleOutput.textContent = res;
                if (pipelineStatus) pipelineStatus.textContent = "Hoàn tất // 0 Vi phạm";
                runButton.disabled = false;
            }, 650);
        });
    }

    // Live Telemetry HUD Simulation
    setInterval(function () {
        var latencyEl = document.getElementById("hud-latency");
        var tokensEl = document.getElementById("hud-tokens");
        var accuracyEl = document.getElementById("hud-accuracy");
        var latencyBar = document.getElementById("hud-latency-bar");
        var tokensBar = document.getElementById("hud-tokens-bar");

        if (latencyEl) {
            var lat = 210 + Math.floor(Math.random() * 32);
            latencyEl.textContent = lat;
            if (latencyBar) latencyBar.style.width = Math.min(100, Math.floor((lat / 300) * 100)) + "%";
        }
        if (tokensEl) {
            var tok = 142 + Math.floor(Math.random() * 24);
            tokensEl.textContent = tok;
            if (tokensBar) tokensBar.style.width = Math.min(100, Math.floor((tok / 180) * 100)) + "%";
        }
        if (accuracyEl) {
            accuracyEl.textContent = (99.7 + Math.random() * 0.2).toFixed(1);
        }
    }, 1600);

    // Live Log Feed Append
    var streamBox = document.getElementById("hud-stream-logs");
    var logSamples = [
        "[BĂNG-CHUYỀN-02] Đếm quang học thời gian thực: 1.480 sp/phút. Tỷ lệ lỗi: 0,00%.",
        "[CSKH-VIỄN-THÔNG] Điều hướng cảm xúc khách hàng: 94,2% hài lòng trên tuyến xử lý cước.",
        "[LƯỚI-ĐIỆN] Hệ số công suất lộ xuất tuyến #14 tối ưu hóa đạt 0,98. Tổn thất phản kháng tối thiểu.",
        "[BỘ-ĐIỀU-PHỐI] Kiểm toán hạn mức thụ động: 0 yêu cầu scraping ra ngoài.",
        "[THỊ-GIÁC-AI] Ảnh nhiệt máy biến áp trạm: Nhiệt độ đỉnh 48,2°C (Ngưỡng an toàn: 75°C).",
        "[ĐỒNG-BỘ-ERP] Lệnh sửa chữa SAP #WO-89105: Đã được Trưởng ca bảo trì phê duyệt."
    ];

    setInterval(function () {
        if (streamBox) {
            var now = new Date();
            var timeStr = now.toTimeString().split(" ")[0];
            var item = logSamples[Math.floor(Math.random() * logSamples.length)];
            var newRow = document.createElement("div");
            newRow.className = "text-muted mb-1";
            newRow.innerHTML = '<span class="text-secondary">[' + timeStr + ']</span> ' + item;
            streamBox.appendChild(newRow);
            if (streamBox.childNodes.length > 25) {
                streamBox.removeChild(streamBox.firstChild);
            }
            streamBox.scrollTop = streamBox.scrollHeight;
        }
    }, 2400);
});
